use super::{reader,shared};
use shared::units::{LengthUnitControl,LengthUnitLimits,LengthUnitResult,LengthUnitWork};
#[semio_framework_async_macros::async_test]
async fn own_neutral_length_units(){let cases:semio_framework_pack_json::Value=semio_framework_pack_json::parse(include_str!("../../../../../../../📐️geometry/📏️units/🧪️tests/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for case in cases["cases"].as_array().unwrap(){let text=format!("ISO-10303-21;HEADER;FILE_DESCRIPTION((''),'2;1');FILE_NAME('','',(''),(''),'','','');FILE_SCHEMA(('IFC2X3'));ENDSEC;DATA;{}ENDSEC;END-ISO-10303-21;",case["data"].as_str().unwrap());let source=semio_s_artifact_stdio_contract::part21::parse_part21(&text).unwrap();let graph=reader::Ifc2x3GeometryGraph(&source);let mut work=LengthUnitWork::new(1,7,LengthUnitLimits::default());let mut result=LengthUnitResult::Pending;for _ in 0..10000{result=work.advance(&graph,7,1,&mut |_|LengthUnitControl::Continue);if result!=LengthUnitResult::Pending{break}}if case["name"].as_str()==Some("nonnegative length alias IFC4"){assert!(matches!(result,LengthUnitResult::Invalid{reason:"invalid-length-factor",..}));}else{match result{LengthUnitResult::Resolved{metres_per_unit,..}=>{assert_eq!(case["expected"]["status"].as_str(),Some("resolved"));let expected=case["expected"]["metresPerUnit"].as_f64().unwrap();assert!((metres_per_unit-expected).abs()<=expected.abs()*1e-14);},LengthUnitResult::Invalid{reason,..}=>{assert_eq!(case["expected"]["status"].as_str(),Some("invalid"));assert_eq!(Some(reason),case["expected"]["reason"].as_str());},other=>panic!("unexpected {:?}",other)}}assert!(work.close(10000,&mut |_|LengthUnitControl::Continue));}}
